<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api, type Page } from './api'
const props = defineProps<{ permissions: string[]; userId: string }>()
interface Row { id: string; orderId: string; confirmationId?: string; sourceRevision: string; externalOrder: string; externalItem: string; externalSchedule: string; plantCode: string; quantity?: string; promisedDate?: string; dueDate?: string; originalDate?: string; proposedDate?: string; kind?: string; reason?: string; status: string; requesterId?: string; version: number }
interface Approval { id: string; actorId: string; decision: string; reason: string; createdAt: string }
const rows = ref<Row[]>([]), page = ref(1), total = ref(0), kind = ref('confirmations'), status = ref(''), busy = ref(false), selected = ref<Row>(), changeOpen = ref(false), decisionOpen = ref(false), historyOpen = ref(false), approvals = ref<Approval[]>([])
const orderVersion = ref(0)
const changeForm = reactive({ proposedDate: '', reason: '' }), decisionForm = reactive({ decision: 'APPROVED', reason: '' })
const states: Record<string, string> = { SUBMITTED: '待采购审批', EFFECTIVE: '已生效', REJECTED: '已拒绝', SUPERSEDED: '版本失效', WITHDRAWN: '已撤回', APPROVED: '已批准', PLANNED: '待发货计划', PARTIALLY_SHIPPED: '部分送货', SHIPPED: '已全部送货' }
async function run(fn: () => Promise<void>) { busy.value = true; try { await fn() } catch (e) { ElMessage.error(e instanceof Error ? e.message : '操作失败') } finally { busy.value = false } }
async function load() { const v = await api<Page<Row>>(`/${kind.value}?page=${page.value - 1}&size=20&status=${status.value || ''}`); rows.value = v.items; total.value = v.total }
async function request(row: Row) { await run(async () => { selected.value = row; orderVersion.value = (await api<{ version: number }>(`/purchase-orders/${row.orderId}`)).version; changeForm.proposedDate = row.promisedDate!; changeForm.reason = ''; changeOpen.value = true }) }
async function saveChange() { await run(async () => { const row = selected.value!; await api(`/purchase-orders/${row.orderId}/delivery-changes`, 'POST', { confirmationId: row.id, sourceRevision: row.sourceRevision, ...changeForm }, orderVersion.value); changeOpen.value = false; await load(); ElMessage.success('改期申请已提交，原承诺保持有效') }) }
function review(row: Row) { selected.value = row; decisionForm.decision = 'APPROVED'; decisionForm.reason = ''; decisionOpen.value = true }
async function decide() { await run(async () => { const row = selected.value!; await api(`/delivery-changes/${row.id}/decision`, 'POST', decisionForm, row.version); decisionOpen.value = false; await load(); ElMessage.success('审批结果已保存') }) }
async function withdraw(row: Row) { await run(async () => { const latest = await api<Row>(`/delivery-changes/${row.id}`); await api(`/delivery-changes/${row.id}/withdraw`, 'POST', undefined, latest.version); await load(); ElMessage.success('申请已撤回') }) }
async function history(row: Row) { await run(async () => { approvals.value = await api<Approval[]>(`/delivery-changes/${row.id}/approval-events`); historyOpen.value = true }) }
onMounted(() => run(load))
</script>
<template><section class="card table-card" v-loading="busy"><div class="toolbar"><el-radio-group v-model="kind" @change="page = 1; status = ''; run(load)"><el-radio-button value="confirmations">供应商确认</el-radio-button><el-radio-button value="delivery-changes">交期申请与审批</el-radio-button><el-radio-button value="delivery-plans">交货计划</el-radio-button></el-radio-group><el-select v-model="status" aria-label="协同状态筛选" placeholder="全部状态" clearable @change="page = 1; run(load)"><el-option v-for="(label, value) in states" :key="value" :value="value" :label="label"/></el-select><el-button @click="run(load)">刷新协同</el-button></div>
<p class="muted">按计划行部分确认。待审批数量预占订单余额，批准后生成等量交货计划；交货计划不代表实际发货或收货。</p><el-table :data="rows" empty-text="暂无授权协同数据"><el-table-column prop="externalOrder" label="采购订单" min-width="150"/><el-table-column prop="externalItem" label="行项目"/><el-table-column prop="externalSchedule" label="计划行"/><el-table-column prop="plantCode" label="工厂"/><el-table-column prop="sourceRevision" label="来源版本"/><el-table-column v-if="kind !== 'delivery-changes'" prop="quantity" label="数量" min-width="130"/>
<el-table-column v-if="kind === 'confirmations'" prop="promisedDate" label="承诺交期" min-width="130"/><el-table-column v-if="kind === 'delivery-plans'" prop="dueDate" label="计划交期" min-width="130"/><template v-if="kind === 'delivery-changes'"><el-table-column label="类型" min-width="130"><template #default="{ row }">{{ row.kind === 'INITIAL' ? '首次延期确认' : '已有承诺改期' }}</template></el-table-column><el-table-column prop="originalDate" label="原日期" min-width="130"/><el-table-column prop="proposedDate" label="申请日期" min-width="130"/><el-table-column prop="reason" label="申请原因" min-width="180"/></template><el-table-column label="状态" min-width="130"><template #default="{ row }">{{ states[row.status] }}</template></el-table-column><el-table-column v-if="kind !== 'delivery-plans'" label="操作" min-width="200"><template #default="{ row }"><el-button v-if="kind === 'confirmations' && row.status === 'EFFECTIVE' && props.permissions.includes('confirmation.submit')" link type="primary" @click="request(row)">申请改期</el-button><template v-if="kind === 'delivery-changes'"><el-button v-if="row.status === 'SUBMITTED' && props.permissions.includes('delivery.approve')" link type="primary" @click="review(row)">审批</el-button><el-button v-if="row.status === 'SUBMITTED' && row.requesterId === props.userId && props.permissions.includes('confirmation.submit')" link type="warning" @click="withdraw(row)">撤回</el-button><el-button link @click="history(row)">审批记录</el-button></template></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next, total" @current-change="run(load)"/></section>
<el-dialog v-model="changeOpen" title="申请变更已生效承诺" width="480px"><p>{{ selected?.externalOrder }} / {{ selected?.externalItem }} / {{ selected?.externalSchedule }} · {{ selected?.quantity }}</p><el-form label-position="top" @submit.prevent="saveChange"><el-form-item label="申请交期"><el-input v-model="changeForm.proposedDate" type="date" aria-label="申请交期"/></el-form-item><el-form-item label="改期原因"><el-input v-model="changeForm.reason" type="textarea" maxlength="1000" aria-label="改期原因"/></el-form-item><el-button type="primary" native-type="submit" :loading="busy">提交改期申请</el-button></el-form></el-dialog>
<el-dialog v-model="decisionOpen" title="采购交期审批" width="500px"><p>{{ selected?.externalOrder }} · {{ selected?.originalDate }} → {{ selected?.proposedDate }}</p><p>{{ selected?.reason }}</p><el-form label-position="top" @submit.prevent="decide"><el-form-item label="审批决定"><el-radio-group v-model="decisionForm.decision"><el-radio value="APPROVED">批准</el-radio><el-radio value="REJECTED">拒绝</el-radio></el-radio-group></el-form-item><el-form-item label="审批意见"><el-input v-model="decisionForm.reason" type="textarea" maxlength="1000" aria-label="审批意见"/></el-form-item><el-button type="primary" native-type="submit" :loading="busy">提交审批决定</el-button></el-form></el-dialog>
<el-drawer v-model="historyOpen" title="不可变审批记录" size="65%"><el-table :data="approvals" empty-text="暂无终态审批记录"><el-table-column label="决定"><template #default="{ row }">{{ states[row.decision] }}</template></el-table-column><el-table-column prop="reason" label="意见"/><el-table-column prop="actorId" label="审批人 ID" min-width="280"/><el-table-column label="时间" min-width="180"><template #default="{ row }">{{ new Date(row.createdAt).toLocaleString() }}</template></el-table-column></el-table></el-drawer></template>
<style scoped>.toolbar{display:flex;gap:12px;flex-wrap:wrap}.toolbar .el-select{max-width:200px}</style>

